/bin/bash -lc "which python3 && python3 -V ; python3 - <<'EOF'
import importlib
for m in (\"torch\",\"timm\",\"transformers\",\"PIL\",\"numpy\"):
    try:
        mod=importlib.import_module(m)
        print(m, getattr(mod,\"__version__\",\"?\"))
    except Exception as e:
        print(m, \"NOT-INSTALLED\")
EOF"

